CREATE TEMP TABLE tt AS
SELECT * FROM (VALUES (1,'Alice'),(2,'Bob')) t(id,name);
SELECT * FROM tt ORDER BY id;

CREATE TEMP VIEW tv AS
SELECT * FROM (VALUES (1,'Alice'),(2,'Bob')) t(id,name);
SELECT * FROM tv ORDER BY id;

CREATE TEMP MACRO add_tax(p) AS p * 1.1;
SELECT name, add_tax(salary) AS total
FROM (VALUES ('Alice',5000)) t(name,salary);

CREATE TEMP MACRO get_dept(d) AS TABLE
SELECT *
FROM (VALUES ('Sales','Alice'),('Tech','Bob')) t(dept,name)
WHERE dept = d;
SELECT * FROM get_dept('Sales');

CREATE TEMP SEQUENCE tmp_seq START 1;
SELECT nextval('tmp_seq') AS id;

PREPARE q AS
SELECT *
FROM (VALUES (1,'Alice'),(2,'Bob')) t(id,name)
WHERE id >= $1;
EXECUTE q(2);
DEALLOCATE q;

ATTACH ':memory:' AS aux;
CREATE TABLE aux.t(i INTEGER);
SELECT * FROM aux.t;
DETACH aux;

ATTACH ':memory:' AS aux2;
CREATE SCHEMA aux2.s;
USE aux2.s;
CREATE TABLE t(i INTEGER);

ATTACH ':memory:' AS db1;
ATTACH ':memory:' AS db2;
SET search_path = 'db1,db2';

CREATE TABLE t AS
SELECT * FROM (VALUES (1,'Alice'),(2,'Bob')) v(id,name);
SELECT * FROM t ORDER BY id;

CREATE VIEW v AS
SELECT * FROM (VALUES (1,'Alice'),(2,'Bob')) t(id,name);
SELECT * FROM v ORDER BY id;

CREATE MACRO bonus_calc(s) AS s * 0.15;
SELECT name, bonus_calc(salary) AS bonus
FROM (VALUES ('Alice',5000)) t(name,salary);

CREATE MACRO filter_by_min_sal(ms) AS TABLE
SELECT *
FROM (VALUES ('Alice',5000),('Bob',7000)) t(name,salary)
WHERE salary >= ms;
SELECT * FROM filter_by_min_sal(6000);

CREATE SCHEMA analytics;
CREATE TABLE analytics.t(i INTEGER);

CREATE SEQUENCE id_seq START 1;
SELECT nextval('id_seq') AS id;

CREATE TABLE idx_demo(id INTEGER, name VARCHAR);
CREATE INDEX idx_demo_id ON idx_demo(id);

CREATE TYPE mood AS ENUM ('happy','sad');
CREATE TABLE people(id INTEGER, state mood);
